"use client";
/* Generated by Antigravity AI - Adhering to SOLID & Design Patterns */


import { Maximize2, Minimize2, Wand2 } from "lucide-react";
import { IArticleFormData } from "../admin-articles.types";

interface Props {
  formData: IArticleFormData;
  setFormData: React.Dispatch<React.SetStateAction<IArticleFormData>>;
  isEdit: boolean;
  isFullscreen: boolean;
  setIsFullscreen: (val: boolean) => void;
  setShowAiModal: (val: boolean) => void;
}

export function ArticleEditorBasicComponent({
  formData,
  setFormData,
  isEdit,
  isFullscreen,
  setIsFullscreen,
  setShowAiModal,
}: Props) {
  const handleTitleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const title = e.target.value;
    const slug = title
      .toLowerCase()
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/đ/g, "d")
      .replace(/[^a-z0-9\s-]/g, "")
      .replace(/\s+/g, "-")
      .replace(/-+/g, "-");

    setFormData((prev) => ({
      ...prev,
      title,
      slug: !isEdit ? slug : prev.slug, // Chỉ tự sinh khi tạo mới
    }));
  };

  return (
    <div
      className={`p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-800 space-y-4 bg-white dark:bg-slate-900 transition-all ${isFullscreen ? "" : "backdrop-blur-md"}`}
    >
      <h2 className="text-lg font-bold text-gray-900 dark:text-gray-100 border-b pb-2 mb-4">
        Nội Dung Bài Viết
      </h2>

      <div>
        <label className="block text-sm font-semibold text-gray-700 dark:text-gray-200 mb-1">
          Tiêu đề bài viết <span className="text-red-500">*</span>
        </label>
        <input
          type="text"
          required
          value={formData.title}
          onChange={handleTitleChange}
          className="w-full px-4 py-2 bg-gray-50 dark:bg-slate-800/50 border rounded-xl outline-none focus:ring-2 focus:ring-blue-500 text-md font-medium"
          placeholder="Nhập tiêu đề..."
        />
      </div>

      <div>
        <label className="block text-sm font-semibold text-gray-700 dark:text-gray-200 mb-1">
          Đường dẫn (Slug) <span className="text-red-500">*</span>
        </label>
        <input
          type="text"
          required
          value={formData.slug}
          onChange={(e) => setFormData({ ...formData, slug: e.target.value })}
          className="w-full px-4 py-2 bg-gray-50 dark:bg-slate-800/50 border rounded-xl outline-none focus:ring-2 focus:ring-blue-500 font-mono text-sm text-gray-700 dark:text-gray-200 bg-gray-50 dark:bg-slate-800/50"
        />
      </div>

      <div>
        <label className="block text-sm font-semibold text-gray-700 dark:text-gray-200 mb-1">
          Tóm tắt (Excerpt)
        </label>
        <textarea
          value={formData.description}
          onChange={(e) =>
            setFormData({ ...formData, description: e.target.value })
          }
          className="w-full px-4 py-2 bg-gray-50 dark:bg-slate-800/50 border rounded-xl outline-none focus:ring-2 focus:ring-blue-500 text-sm h-20 resize-none"
          placeholder="Đoạn tóm tắt ngắn gọn hiển thị ở danh sách bài viết..."
        />
      </div>

      <div>
        <div className="flex items-center justify-between mb-2">
          <label className="block text-sm font-semibold text-gray-700 dark:text-gray-200">
            Nội dung chi tiết <span className="text-red-500">*</span>
          </label>
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={() => setIsFullscreen(!isFullscreen)}
              className="text-xs font-bold text-gray-600 dark:text-gray-300 bg-gray-100 hover:bg-gray-200 dark:bg-slate-800 dark:hover:bg-slate-700 px-3 py-1.5 rounded-lg flex items-center gap-1 transition-colors"
            >
              {isFullscreen ? (
                <>
                  <Minimize2 size={14} /> Thu nhỏ
                </>
              ) : (
                <>
                  <Maximize2 size={14} /> Phóng to
                </>
              )}
            </button>
            <button
              type="button"
              onClick={() => setShowAiModal(true)}
              className="text-xs font-bold text-violet-600 bg-violet-50 hover:bg-violet-100 dark:bg-slate-800 dark:hover:bg-slate-700 dark:text-violet-400 px-3 py-1.5 rounded-lg flex items-center gap-1 transition-colors"
            >
              <Wand2 size={14} /> Trợ lý AI
            </button>
          </div>
        </div>
        <div
          className={`border border-gray-100 dark:border-slate-800 rounded-xl overflow-hidden ${
            isFullscreen
              ? "fixed inset-0 z-[9999] shadow-2xl flex flex-col bg-white dark:bg-slate-900"
              : "h-[500px] bg-white/50 dark:bg-slate-900/50 backdrop-blur-md"
          }`}
        >
          {isFullscreen && (
            <div className="p-3 bg-gray-50 dark:bg-slate-950 border-b flex justify-between items-center">
              <span className="font-bold z-50 text-gray-700 dark:text-gray-200">
                Chế độ soạn thảo toàn màn hình
              </span>
              <button
                type="button"
                onClick={() => setIsFullscreen(false)}
                className="p-1 hover:bg-gray-200 rounded"
              >
                <Minimize2 size={18} />
              </button>
            </div>
          )}
          <div className={`p-3 ${isFullscreen ? "flex-1 flex flex-col" : "h-full flex flex-col"}`}>
            <textarea
              value={formData.content}
              onChange={(e) => setFormData({ ...formData, content: e.target.value })}
              className="w-full flex-1 p-4 bg-transparent outline-none font-mono text-sm resize-none text-slate-800 dark:text-slate-100 placeholder:text-slate-400"
              placeholder="Nhập nội dung bài viết chuẩn SEO (hỗ trợ văn bản, HTML)..."
            />
          </div>
        </div>
      </div>
    </div>
  );
}
